// Wrong: network on the main thread -> frozen UI, ANR (Android throws NetworkOnMainThreadException)
val user = api.getUser(id)

// Right: suspend + background dispatcher, update UI state back on main
class ProfileViewModel(private val api: Api) : ViewModel() {
    val state = MutableStateFlow<User?>(null)
    fun load(id: String) = viewModelScope.launch {          // runs on Main
        val user = withContext(Dispatchers.IO) { api.getUser(id) } // network off main
        state.value = user                                     // back on Main
    }
}

class ProfileViewModel(private val repo: UserRepository) : ViewModel() {
    val state = MutableStateFlow<UiState>(UiState.Loading)
    fun load(id: String) = viewModelScope.launch {
        state.value = runCatching { repo.getUser(id) } // repo switches to IO inside
            .fold({ UiState.Success(it) }, { UiState.Error(it.message) })
    }
}

