// Retry only idempotent calls, with exponential backoff + jitter
suspend fun <T> retrying(times: Int = 3, block: suspend () -> T): T {
    var delayMs = 500L
    repeat(times - 1) {
        try { return block() } catch (e: IOException) {
            delay(delayMs + Random.nextLong(200))
            delayMs *= 2
        }
    }
    return block() // last attempt: let the error reach the UI ("Retry" button)
}

